from hypothesis import strategies as st
import itertools


@st.composite
def gen(draw):
    N = draw(st.integers(2, 5))
    # spanning tree: vertex i connects to some earlier vertex
    tree = []
    tree_set = set()
    for i in range(2, N + 1):
        p = draw(st.integers(1, i - 1))
        tree.append((p, i))
        tree_set.add((p, i))
    pairs = [(a, b) for a in range(1, N + 1) for b in range(a + 1, N + 1)
             if (a, b) not in tree_set]
    extra = []
    if pairs:
        extra = draw(st.lists(st.sampled_from(pairs), unique=True, max_size=len(pairs)))
    edges = tree + extra
    edges = draw(st.permutations(edges))
    lines_e = []
    for (u, v) in edges:
        w = draw(st.integers(1, 5))
        lines_e.append((u, v, w))
    # disjoint vertex sets for A and B
    perm = draw(st.permutations(list(range(1, N + 1))))
    cut = draw(st.integers(1, N - 1))
    SA = list(perm[:cut])
    SB = list(perm[cut:])
    K = draw(st.integers(1, N))
    A = [draw(st.sampled_from(SA)) for _ in range(K)]
    B = [draw(st.sampled_from(SB)) for _ in range(K)]
    out = [f"{N} {len(lines_e)} {K}"]
    for (u, v, w) in lines_e:
        out.append(f"{u} {v} {w}")
    out.append(" ".join(map(str, A)))
    out.append(" ".join(map(str, B)))
    return "\n".join(out) + "\n"


def _parse(inp):
    t = inp.split()
    pos = 0
    N = int(t[pos]); M = int(t[pos + 1]); K = int(t[pos + 2]); pos += 3
    edges = []
    for _ in range(M):
        u = int(t[pos]); v = int(t[pos + 1]); w = int(t[pos + 2]); pos += 3
        edges.append((u, v, w))
    A = [int(x) for x in t[pos:pos + K]]; pos += K
    B = [int(x) for x in t[pos:pos + K]]; pos += K
    if pos != len(t):
        raise ValueError("extra tokens")
    return N, M, K, edges, A, B


def validate(inp):
    try:
        N, M, K, edges, A, B = _parse(inp)
        if not (2 <= N <= 2 * 10**5):
            return False
        if not (N - 1 <= M <= min(N * (N - 1) // 2, 2 * 10**5)):
            return False
        if not (1 <= K <= N):
            return False
        seen = set()
        for (u, v, w) in edges:
            if not (1 <= u < v <= N):
                return False
            if (u, v) in seen:
                return False
            seen.add((u, v))
            if not (1 <= w <= 10**9):
                return False
        if any(not (1 <= x <= N) for x in A + B):
            return False
        if set(A) & set(B):
            return False
        # connectivity
        adj = {i: [] for i in range(1, N + 1)}
        for (u, v, w) in edges:
            adj[u].append(v)
            adj[v].append(u)
        vis = {1}
        st_ = [1]
        while st_:
            x = st_.pop()
            for y in adj[x]:
                if y not in vis:
                    vis.add(y)
                    st_.append(y)
        return len(vis) == N
    except Exception:
        return False


def _connected(N, edges, x, y, t):
    par = list(range(N + 1))

    def find(a):
        while par[a] != a:
            par[a] = par[par[a]]
            a = par[a]
        return a

    for (u, v, w) in edges:
        if w <= t:
            ru, rv = find(u), find(v)
            if ru != rv:
                par[ru] = rv
    return find(x) == find(y)


def _f(N, edges, x, y):
    # literal definition: min threshold t such that x,y connected using edges of weight <= t
    for t in sorted(set(w for _, _, w in edges)):
        if _connected(N, edges, x, y, t):
            return t
    return None


def ref(inp):
    N, M, K, edges, A, B = _parse(inp)
    best = None
    for perm in itertools.permutations(B):
        s = 0
        for i in range(K):
            s += _f(N, edges, A[i], perm[i])
        if best is None or s < best:
            best = s
    return str(best)
