@st.composite
def gen(draw):
    N = draw(st.integers(2, 5))
    all_pairs = [(u, v) for u in range(1, N + 1) for v in range(u + 1, N + 1)]
    # random spanning tree guarantees connectivity
    chosen = set()
    for i in range(2, N + 1):
        par = draw(st.integers(1, i - 1))
        chosen.add((min(par, i), max(par, i)))
    rest = [pr for pr in all_pairs if pr not in chosen]
    if rest:
        extra = draw(st.lists(st.sampled_from(rest), unique=True, max_size=len(rest)))
        chosen.update(extra)
    edge_list = sorted(chosen)
    draw(st.randoms(use_true_random=False))
    ws = [draw(st.sampled_from([1, 2, 3, 5, 10, 10**9])) for _ in edge_list]
    edges = [(u, v, w) for (u, v), w in zip(edge_list, ws)]
    perm = draw(st.permutations(list(range(1, N + 1))))
    ka = draw(st.integers(1, N - 1))
    sA = perm[:ka]
    sB = perm[ka:]
