    B = draw(st.lists(st.sampled_from(sB), min_size=K, max_size=K))
    lines = [f"{N} {len(edges)} {K}"]
    for u, v, w in edges:
        lines.append(f"{u} {v} {w}")
    lines.append(" ".join(map(str, A)))
    lines.append(" ".join(map(str, B)))
    return "\n".join(lines) + "\n"


def validate(inp):
    try:
        t = inp.split()
        N, M, K = int(t[0]), int(t[1]), int(t[2])
        if not (2 <= N <= 2 * 10**5):
