            return False
        if len(A) != K or len(B) != K:
            return False
        if not all(1 <= x <= N for x in A + B):
            return False
        if set(A) & set(B):
            return False
        return True
    except Exception:
        return False


def _f(N, edges, x, y):
    # literal definition: smallest threshold t such that x,y connected
    # using only edges of weight <= t
    for t_ in sorted({w for _, _, w in edges}):
        adj = [[] for _ in range(N + 1)]
        for u, v, w in edges:
            if w <= t_:
                adj[u].append(v)
                adj[v].append(u)
        seen = {x}
        stack = [x]
        while stack:
            c = stack.pop()
            for d in adj[c]:
                if d not in seen:
                    seen.add(d)
                    stack.append(d)
        if y in seen:
            return t_
    return None


def ref(inp):
    N, M, K, edges, A, B, _ = _parse(inp)
    cost = [[_f(N, edges, A[i], B[j]) for j in range(K)] for i in range(K)]
    best = None
    for perm in itertools.permutations(range(K)):
        s = sum(cost[i][perm[i]] for i in range(K))
